package com.orient.ortts.demo;

import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;

/** Anonymous metadata discovery only. Selection/download never follows a moving manifest. */
final class OwnModelCatalog {
 static final String OWNER="OrientLuna",API="https://modelscope.cn/api/v1/models",ROOT="https://modelscope.cn/models/";
 static final int LIMIT=2*1024*1024;
 static String sha(byte[] b)throws Exception{StringBuilder s=new StringBuilder();for(byte v:MessageDigest.getInstance("SHA-256").digest(b))s.append(String.format(Locale.ROOT,"%02x",v&255));return s.toString();}
 static boolean repo(String s){return s!=null&&s.matches("OrientLuna/OrTTS-[A-Za-z0-9._-]+");}
 static boolean path(String s){return s!=null&&!s.isEmpty()&&!s.startsWith("/")&&s.matches("[A-Za-z0-9._/-]+")&&!Arrays.asList(s.split("/",-1)).contains("..")&&!Arrays.asList(s.split("/",-1)).contains(".")&&!s.contains("//");}
 static String key(JSONObject m){return m.optString("id")+"@"+m.optString("manifest_sha256");}
 static boolean validEntry(JSONObject m){try{String id=m.getString("id"),h=m.getString("manifest_sha256");if(!repo(id)||!h.matches("[a-f0-9]{64}")||!m.getString("revision").matches("[A-Za-z0-9][A-Za-z0-9._-]{0,127}"))return false;
  if(m.optString("source").equals("modelscope")){JSONArray variants=m.getJSONArray("supported_variants"),voices=m.getJSONArray("voices");if(variants.length()<1||variants.length()>2||voices.length()<1||voices.length()>4||!Arrays.asList("qwen_lfm","liquidcodec").contains(m.getString("decoder")))return false;for(int i=0;i<variants.length();i++)if(!Arrays.asList("P3","P5").contains(variants.getString(i)))return false;for(int i=0;i<voices.length();i++)if(!Arrays.asList("female","female_2","male","male_2").contains(voices.getString(i)))return false;String commit=m.getString("source_commit"),p=m.getString("manifest_path");if(!commit.matches("[a-f0-9]{40}")||!path(p)||!(p.equals("DOWNLOAD_MANIFEST.json")||p.endsWith("/DOWNLOAD_MANIFEST.json")))return false;if(!m.getString("manifest_url").equals(ROOT+id+"/resolve/"+commit+"/"+p))return false;}
  else {URL u=new URL(m.getString("manifest_url"));if(!u.getProtocol().equals("https")||!u.getHost().equals("modelscope.cn")||!u.getPath().startsWith("/models/"+id+"/resolve/"))return false;}
  return true;}catch(Exception e){return false;}}
 static List<String> repositories(JSONObject response)throws Exception{if(response.getInt("Code")!=200)throw new IOException("ModelScope目录请求失败");JSONArray list=response.getJSONObject("Data").getJSONArray("Models");List<String> out=new ArrayList<>();for(int i=0;i<list.length();i++){JSONObject m=list.getJSONObject(i);String id=m.optString("Path")+"/"+m.optString("Name");if(repo(id)&&!out.contains(id))out.add(id);}return out;}
 static List<JSONObject> manifests(String repo,JSONObject response)throws Exception{if(!repo(repo)||response.getInt("Code")!=200)throw new IOException("无效模型仓库");List<JSONObject> out=new ArrayList<>();JSONArray files=response.getJSONObject("Data").getJSONArray("Files");for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);String p=f.optString("Path"),c=f.optString("Revision"),h=f.optString("Sha256");if(path(p)&&(p.equals("DOWNLOAD_MANIFEST.json")||p.endsWith("/DOWNLOAD_MANIFEST.json"))&&c.matches("[a-f0-9]{40}")&&h.matches("[a-f0-9]{64}")&&f.optLong("Size")>0&&f.optLong("Size")<=LIMIT)out.add(new JSONObject().put("id",repo).put("source_commit",c).put("manifest_path",p).put("manifest_sha256",h).put("manifest_url",ROOT+repo+"/resolve/"+c+"/"+p).put("source","modelscope"));}out.sort(Comparator.comparing(x->x.optString("manifest_path")));return out;}
 static JSONObject normalize(JSONObject source,byte[] bytes)throws Exception{
  if(bytes.length>LIMIT||!sha(bytes).equals(source.getString("manifest_sha256")))throw new IOException("目录清单SHA不匹配");JSONObject m=new JSONObject(new String(bytes,StandardCharsets.UTF_8));if(!m.optString("schema").equals("ortts-download-manifest-v1")||!m.optString("model_id").equals(source.getString("id"))||!m.optString("revision").matches("[A-Za-z0-9][A-Za-z0-9._-]{0,127}"))throw new IOException("非兼容自研模型包");
  if(m.has("runtime")&&!(m.get("runtime") instanceof JSONObject)&&!(m.get("runtime") instanceof String))throw new IOException("未知运行时描述");JSONObject runtime=m.optJSONObject("runtime"),decoder=runtime==null?null:runtime.optJSONObject("decoder");String kind=decoder==null?"qwen_lfm":decoder.optString("kind");if(runtime!=null&&(!runtime.optString("schema").equals("ortts-runtime-v1")||decoder==null))throw new IOException("未知运行时schema");if(!kind.equals("qwen_lfm")&&!kind.equals("liquidcodec"))throw new IOException("未知声学解码器");
  JSONArray files=m.getJSONArray("files");if(files.length()<1||files.length()>256)throw new IOException("模型文件数量异常");Set<String> paths=new HashSet<>();JSONArray voices=new JSONArray();Map<String,Long> sizes=new LinkedHashMap<>();long all=0;for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);String p=f.getString("path");long n=f.getLong("bytes");if(!path(p)||!paths.add(p)||!f.getString("sha256").matches("[a-f0-9]{64}")||n<0||n>8L*1024*1024*1024)throw new IOException("文件条目无效");all+=n;sizes.put(p,n);if(p.matches("voices/[A-Za-z0-9_-]+\\.f32"))voices.put(p.substring(7,p.length()-4));}if(all>8L*1024*1024*1024||!paths.containsAll(Arrays.asList("native/model.gguf","voices/female.f32","voices/male.f32")))throw new IOException("非完整自研运行包");
  if(kind.equals("liquidcodec")&&(!Arrays.asList("base","expanded").contains(decoder.optString("variant"))||!path(decoder.optString("manifest"))||!decoder.optString("manifest").endsWith("/runtime.json")||!paths.contains(decoder.optString("manifest"))))throw new IOException("声学清单不完整");if(decoder!=null&&decoder.has("dequant_manifest")&&(!path(decoder.getString("dequant_manifest"))||!decoder.getString("dequant_manifest").endsWith("/MANIFEST.json")||!paths.contains(decoder.getString("dequant_manifest"))))throw new IOException("dequant清单不完整");
  JSONObject rules=m.getJSONObject("selection_rules");Map<String,List<String>> patterns=new LinkedHashMap<>();for(String k:new String[]{"common","P3","P5"}){JSONArray a=rules.getJSONArray(k);List<String> v=new ArrayList<>();for(int i=0;i<a.length();i++)v.add(a.getString(i));patterns.put(k,v);}
  JSONObject policy=m.optJSONObject("research_policy");boolean p3Only=policy!=null;if(p3Only&&(!policy.optString("schema").equals("ortts-ptq-lazy-qa-v1")||policy.optInt("expected_talker_matrices")!=196||policy.optInt("training_steps",-1)!=0||!kind.equals("liquidcodec")||m.optInt("speaker_dimension")!=1024||!((policy.optInt("expected_talker_type")==2&&policy.optBoolean("lazy_import_scratch"))||(policy.optInt("expected_talker_type")==8&&!policy.optBoolean("lazy_import_scratch")))))throw new IOException("未知PTQ策略");
  JSONArray variants=m.optJSONArray("supported_variants");if(variants==null)variants=new JSONArray(p3Only?new String[]{"P3"}:new String[]{"P3","P5"});JSONArray usable=new JSONArray();JSONObject out=new JSONObject(source.toString());for(int i=0;i<variants.length();i++){String v=variants.getString(i);if(!v.equals("P3")&&!v.equals("P5")||p3Only&&!v.equals("P3"))throw new IOException("不兼容的P3/P5范围");if(v.equals("P3")&&(!paths.contains("P3/predictor/config.json")||!paths.contains("P3/predictor/talker_config.json")||(!paths.contains("P3/predictor/predictor.gguf")&&!paths.contains("P3/predictor/predictor.safetensors"))))throw new IOException("P3预测器不完整");long total=0;for(String p:DownloadSelection.select(paths,patterns,v))total+=sizes.get(p);out.put(v+"_bytes",total);usable.put(v);}if(usable.length()==0)throw new IOException("没有可用配置");
  List<String> ordered=new ArrayList<>();for(String v:new String[]{"female","female_2","male","male_2"})if(paths.contains("voices/"+v+".f32"))ordered.add(v);
  out.put("name",m.optString("display_name",source.getString("id").substring(OWNER.length()+1))+" · "+m.getString("revision")).put("revision",m.getString("revision")).put("supported_variants",usable).put("voices",new JSONArray(ordered)).put("decoder",kind).put("p3_only",p3Only);if(!validEntry(out))throw new IOException("目录身份无效");return out;
 }
 static JSONArray merge(JSONArray... arrays){LinkedHashMap<String,JSONObject> map=new LinkedHashMap<>();for(JSONArray a:arrays)for(int i=0;i<a.length();i++){JSONObject m=a.optJSONObject(i);if(m!=null&&validEntry(m)){if(!map.containsKey(key(m))&&map.size()<64)map.put(key(m),m);}}return new JSONArray(map.values());}
 private static byte[] request(String url,String body)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(10000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","OrTTS-ModelCatalog/1");if(body!=null){c.setRequestMethod("PUT");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream o=c.getOutputStream()){o.write(body.getBytes(StandardCharsets.UTF_8));}}
  try{if(c.getResponseCode()!=200)throw new IOException("ModelScope目录HTTP "+c.getResponseCode());try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>LIMIT)throw new IOException("目录过大");out.write(b,0,n);}return out.toByteArray();}}finally{c.disconnect();}}
 static JSONArray refresh(JSONArray previous)throws Exception{long deadline=System.nanoTime()+60_000_000_000L;JSONArray found=new JSONArray();List<String> repos=new ArrayList<>();for(int page=1;page<=4;page++){JSONObject r=new JSONObject(new String(request(API,new JSONObject().put("Path",OWNER).put("PageNumber",page).put("PageSize",50).toString()),StandardCharsets.UTF_8));for(String repo:repositories(r))if(!repos.contains(repo))repos.add(repo);if(page*50>=r.getJSONObject("Data").getInt("TotalCount"))break;}
  Map<String,JSONObject> cached=new HashMap<>();for(int i=0;i<previous.length();i++){JSONObject m=previous.optJSONObject(i);if(m!=null&&validEntry(m))cached.put(key(m),m);}int scanned=0;
  for(String repo:repos){if(++scanned>8||System.nanoTime()>deadline)break;try{JSONObject listing=new JSONObject(new String(request(API+"/"+repo+"/repo/files?Revision=master&Recursive=true",null),StandardCharsets.UTF_8));int count=0;for(JSONObject source:manifests(repo,listing)){if(++count>8||found.length()>=32||System.nanoTime()>deadline)break;try{JSONObject old=cached.get(key(source));found.put(old!=null?old:normalize(source,request(source.getString("manifest_url"),null)));}catch(Exception unsupported){/* Unknown or damaged package never replaces a known entry. */}}}catch(Exception offline){/* Preserve earlier repository versions in the private cache. */}}
  if(found.length()==0)throw new IOException("暂未发现兼容的自研发布清单，保留离线目录");return merge(previous,found);
 }
 static JSONArray cached(File file){try{if(file.length()>LIMIT)throw new IOException("目录缓存过大");JSONObject j=new JSONObject(new String(java.nio.file.Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8));return merge(j.getJSONArray("models"));}catch(Exception e){return new JSONArray();}}
 static void save(File file,JSONArray models)throws Exception{JSONObject j=new JSONObject().put("schema","ortts-own-catalog-v1").put("updated_ms",System.currentTimeMillis()).put("models",models);File temp=new File(file.getPath()+".tmp");java.nio.file.Files.write(temp.toPath(),j.toString().getBytes(StandardCharsets.UTF_8));java.nio.file.Files.move(temp.toPath(),file.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);}
}
